INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8aac-7e3b-962b-55fd51c7fe7d'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Simplify 6a^5b^2 ÷ 3a^2b.', '2a^3b', 'Divide coefficients: 6 ÷ 3 = 2. Subtract the powers: a^(5-2) = a^3 and b^(2-1) = b. So the simplified form is 2a^3b.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.204Z'::timestamptz, '2026-08-15T07:36:12.204Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8ac0-78dc-b100-100cc1a63716'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Use the laws of indices to find the value of k if 2^k × 2^4 = 64.', '2', 'Combine the powers: 2^(k+4) = 64. Since 64 = 2^6, we get k + 4 = 6. Therefore k = 2.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.224Z'::timestamptz, '2026-08-15T07:36:12.224Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8ad4-7bcd-8a6b-a92c5be59534'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A number p has exactly 12 factors. Two of its factors are 4 and 15. Find one possible value of p.', '60', 'The number must be divisible by both 4 and 15, so it must be a multiple of 60. Now 60 = 2^2 × 3 × 5, so the number of factors is (2+1)(1+1)(1+1) = 12. Therefore one possible value is 60.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.244Z'::timestamptz, '2026-08-15T07:36:12.244Z'::timestamptz) ON CONFLICT (id) DO NOTHING;